// Callback-based data service — needs refactoring to async/await.

type Callback<T> = (error: Error | null, result: T | null) => void;

/** Simulate async data fetch using callbacks. */
export function fetchUserCb(id: number, cb: Callback<{ id: number; name: string }>): void {
  setTimeout(() => {
    if (id <= 0) {
      cb(new Error('Invalid ID'), null);
    } else {
      cb(null, { id, name: `User${id}` });
    }
  }, 0);
}

/** Simulate async save using callbacks. */
export function saveUserCb(
  user: { id: number; name: string },
  cb: Callback<boolean>
): void {
  setTimeout(() => {
    if (!user.name) {
      cb(new Error('Name required'), null);
    } else {
      cb(null, true);
    }
  }, 0);
}

