import { fetchUser, saveUser, withRetry } from './dataService';

test('fetchUser returns user for valid id', async () => {
  const user = await fetchUser(1);
  expect(user.id).toBe(1);
  expect(user.name).toBe('User1');
});

test('fetchUser throws for invalid id', async () => {
  await expect(fetchUser(-1)).rejects.toThrow('Invalid ID');
});

test('saveUser returns true for valid user', async () => {
  const result = await saveUser({ id: 1, name: 'Alice' });
  expect(result).toBe(true);
});

test('saveUser throws for missing name', async () => {
  await expect(saveUser({ id: 1, name: '' })).rejects.toThrow('Name required');
});

test('withRetry succeeds on first try', async () => {
  const result = await withRetry(() => Promise.resolve(42));
  expect(result).toBe(42);
});

test('withRetry retries on failure then succeeds', async () => {
  let attempts = 0;
  const result = await withRetry(async () => {
    attempts++;
    if (attempts < 3) throw new Error('not yet');
    return 'done';
  }, 3);
  expect(result).toBe('done');
  expect(attempts).toBe(3);
});

test('withRetry throws after max retries', async () => {
  await expect(
    withRetry(() => Promise.reject(new Error('always')), 2)
  ).rejects.toThrow('always');
});
